(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.TrigEquationLesson,num=window.LinearLesson;
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
function piTex(n,d=1){const q=num.rational(n,d);if(q.n===0)return '0';const top=Math.abs(q.n)===1?'\\pi':Math.abs(q.n)+'\\pi';return(q.n<0?'-':'')+(q.d===1?top:`\\frac{${top}}{${q.d}}`);}
function angleTex(x){return piTex(Math.round(x/Math.PI*12),12);}
const intervals={turn:{lo:0,hi:2*Math.PI,closed:false},closed:{lo:0,hi:2*Math.PI,closed:true},signed:{lo:-Math.PI,hi:Math.PI,closed:true},double:{lo:0,hi:4*Math.PI,closed:false}};
function draw(){const kind=$('#eq-kind').value,target=Number($('#eq-target').value)/2,b=Number($('#eq-b').value),range=intervals[$('#eq-interval').value],{lo,hi,closed}=range,roots=core.roots(kind,target,b,lo,hi,closed),fn=kind==='sin'?String.raw`\sin`:String.raw`\cos`,targetTex=Number.isInteger(target)?String(target):String.raw`\frac{${target*2}}2`;$('#target-output').value=target.toString().replace('.',',');math($('#eq-formula'),fn+' '+(b===1?'x':String.raw`(${b}x)`)+String.raw`=${targetTex},\qquad x\in[${angleTex(lo)},${angleTex(hi)}${closed?']':')'}`);let grid='';for(let i=0;i<=4;i++){const x=lo+(hi-lo)*i/4,p=core.point(x,0,lo,hi);grid+=`<line x1="${p.x}" x2="${p.x}" y1="25" y2="265" class="wave-grid-line"/>`;}for(const y of [-1,0,1]){const p=core.point(0,y,lo,hi);grid+=`<line x1="48" x2="610" y1="${p.y}" y2="${p.y}" class="${y===0?'wave-axis':'wave-grid-line'}"/><text x="38" y="${p.y+5}" text-anchor="end" class="wave-grid-label">${y}</text>`;}const axis=core.point(0,0,lo,hi).x;grid+=`<path d="M${axis} 25V265" class="wave-axis"/>`;$('#eq-grid').innerHTML=grid;$('#eq-ticks').innerHTML=Array.from({length:5},(_,i)=>`<span data-tex="${angleTex(lo+(hi-lo)*i/4)}"></span>`).join('');$('#eq-curve').setAttribute('d',core.curve(kind,b,lo,hi).map((p,i)=>`${i?'L':'M'}${p.x} ${p.y}`).join(' '));const y=core.point(0,target,lo,hi).y;for(const [key,v]of Object.entries({x1:48,x2:610,y1:y,y2:y}))$('#eq-target-line').setAttribute(key,v);const excluded=!closed&&Math.abs(target)<=1&&Math.abs(core.value(kind,hi,b)-target)<1e-10;$('#eq-roots').innerHTML=roots.map(x=>{const p=core.point(x,target,lo,hi);return `<circle cx="${p.x}" cy="${p.y}" r="5" class="solution-dot"/>`;}).join('')+(excluded?`<circle cx="610" cy="${y}" r="5" class="excluded-dot"/>`:'');math($('#eq-solutions'),roots.length?String.raw`x\in\left\{${roots.map(angleTex).join(',\ ')}\right\}`:String.raw`\text{Tidak ada solusi pada interval ini.}`);const note=`Ada ${roots.length} solusi pada interval yang dipilih. `+(Math.abs(target)>1?'Nilai target berada di luar range sinus dan kosinus.':excluded?'Perpotongan pada batas kanan tidak dihitung karena batasnya terbuka.':closed?'Kedua batas interval ikut diperiksa; sudut berbeda pada kedua batas tetap ditulis jika keduanya memenuhi.':'Batas kiri masuk, batas kanan tidak masuk.');$('#eq-note').textContent=note;$('#eq-plot').setAttribute('aria-label',`Grafik ${kind==='sin'?'sinus':'kosinus'} dengan koefisien sudut ${b}, garis target ${target}. ${note} Solusi dalam radian sekitar ${roots.length?roots.map(x=>x.toFixed(4)).join('; '):'tidak ada'}.`);}
for(const id of ['eq-kind','eq-target','eq-b','eq-interval'])$('#'+id).addEventListener('input',draw);function preset(target,interval){$('#eq-kind').value='sin';$('#eq-target').value=target;$('#eq-b').value='1';$('#eq-interval').value=interval;draw();}$('#eq-edge').addEventListener('click',()=>preset(0,'closed'));$('#eq-reset').addEventListener('click',()=>preset(1,'turn'));draw();
const questions=[{tex:String.raw`\sin x=0,\quad x\in[0,2\pi]`,prompt:'Berapa banyak solusi pada interval ini?',n:3,d:1,hint:'Kedua batas termasuk interval. Periksa nol, pi, dan dua pi.',why:'Nol, pi, dan dua pi semuanya memenuhi. Kedua batas adalah sudut yang berbeda meskipun titik lingkarannya sama.'},{tex:String.raw`\sin x=3/2,\quad x\in[0,2\pi)`,prompt:'Berapa banyak solusi real pada interval ini?',n:0,d:1,hint:'Nilai sinus tidak melebihi satu.',why:'Target satu setengah berada di luar range sinus, sehingga tidak ada solusi real.'},{tex:String.raw`\sin(2x)=1/2,\quad x\in[0,2\pi)`,prompt:'Berapa banyak solusi pada interval ini?',n:4,d:1,hint:'Sudut dua x menjelajahi dua putaran, masing-masing dengan dua solusi.',why:'Keempat solusi adalah pi per dua belas, lima pi per dua belas, tiga belas pi per dua belas, dan tujuh belas pi per dua belas.'}];const solved=new Set();function report(i,ok,text){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=text;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><p>${q.prompt}</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=num.parseAnswer($('#answer'+i).value),ok=num.equalAnswer(a,num.rational(q.n,q.d));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis jumlah solusi sebagai bilangan bulat, misalnya 0 atau 2.':'Belum tepat. Periksa nilai target, seluruh cabang, dan batas interval.');}));
const choices=[{tex:String.raw`\cos x=-1/2,\quad x\in[0,2\pi)`,prompt:'Manakah seluruh solusinya?',options:[{tex:String.raw`x=\pi/3,\ 5\pi/3`,label:'Pi per tiga dan lima pi per tiga'},{tex:String.raw`x=2\pi/3,\ 4\pi/3`,label:'Dua pi per tiga dan empat pi per tiga'},{tex:String.raw`x=2\pi/3`,label:'Hanya dua pi per tiga'}],answer:1,why:'Kosinus negatif di kuadran II dan III. Kedua sudut memiliki sudut acuan pi per tiga.'},{tex:String.raw`\tan x=1`,prompt:'Manakah solusi umum untuk sudut real?',options:[{tex:String.raw`x=\pi/4+k\pi,\quad k\in\mathbb Z`,label:'Pi per empat ditambah k pi, k bilangan bulat'},{tex:String.raw`x=\pi/4+2k\pi,\quad k\in\mathbb Z`,label:'Pi per empat ditambah dua k pi, k bilangan bulat'},{tex:String.raw`x=\pi/4`,label:'Hanya pi per empat'}],answer:0,why:'Tangen berperiode pi. Menambah dua pi saja melewatkan satu dari setiap dua solusi.'},{tex:String.raw`\sin x\cos x=\sin x`,prompt:'Apa langkah yang menjaga seluruh solusi?',options:[{text:'Langsung membagi kedua sisi dengan sinus.'},{text:'Menyimpulkan kosinus selalu satu untuk semua solusi.'},{text:'Pindahkan suku dan faktorkan menjadi sinus dikali (kosinus dikurangi satu) sama dengan nol.'}],answer:2,why:'Faktorisasi mempertahankan cabang sinus nol. Membagi dengan sinus tanpa memeriksa nol dapat menghilangkan solusi.'}];for(let j=0;j<choices.length;j++){const i=j+3,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="choice${i}" value="${k}" ${o.label?'aria-label="'+o.label+'"':''}>${o.tex?'<span data-tex="'+o.tex+'"></span>':o.text}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-trig-equations-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-trig-equations-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();